_MAX_LOGGED_ARGS = 16 * 1024

@staticmethod
def _logged_args(tool, args):
    if tool == "write_file" and "content" in args:
        data = str(args.get("content", "")).encode("utf-8")
        return {k: v for k, v in args.items() if k != "content"} | {
            "content_bytes": len(data), "content_sha256": hashlib.sha256(data).hexdigest()}
    blob = json.dumps(args, ensure_ascii=False, default=str).encode()
    if len(blob) > _MAX_LOGGED_ARGS:
        return {"args_truncated": True, "args_bytes": len(blob),
                "args_sha256": hashlib.sha256(blob).hexdigest(),
                "args_head": blob[:_MAX_LOGGED_ARGS].decode(errors="replace")}
    return args
